@page "/chat"
@using sv_671ec9cdd931495b825dc5d9d4ba059b.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannel?.Id"
                    OnChannelSelected="SelectChannel" />

    <div class="chat-main @(threadOpen ? "with-thread" : "")">
        @if (selectedChannel is not null)
        {
            <MessageArea ChannelName="@selectedChannel.Name"
                         ChannelDescription="@selectedChannel.Description"
                         Messages="messages"
                         ThreadReplyCounts="threadReplyCounts"
                         IsLoadingMore="isLoadingMore"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnSendMessage="SendMessage"
                         OnLoadMore="LoadOlderMessages" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (threadOpen && threadRootMessage is not null)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = new();
    private Channel? selectedChannel;
    private List<Message> messages = new();
    private Dictionary<int, int> threadReplyCounts = new();
    private bool isLoadingMore;

    private bool threadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = new();

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannel = channel;
        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        threadReplyCounts = await BuildThreadCounts(messages);
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channel list to update unread counts
        channels = await ChatService.GetChannelsAsync();
        CloseThreadSync();
    }

    private async Task LoadOlderMessages()
    {
        if (selectedChannel is null || isLoadingMore) return;
        isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(selectedChannel.Id, messages.Count, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            var olderCounts = await BuildThreadCounts(older);
            foreach (var kvp in olderCounts)
                threadReplyCounts.TryAdd(kvp.Key, kvp.Value);
        }

        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(Message message)
    {
        threadRootMessage = message;
        threadReplies = await ChatService.GetThreadAsync(message.Id);
        threadOpen = true;
    }

    private void CloseThreadSync()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = new();
    }

    private async Task CloseThread()
    {
        CloseThreadSync();
        await Task.CompletedTask;
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannel is null || threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update reply count
        threadReplyCounts[threadRootMessage.Id] =
            threadReplyCounts.GetValueOrDefault(threadRootMessage.Id) + 1;
    }

    private async Task HandleReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
        // Refresh messages to show updated reactions
        if (selectedChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(selectedChannel.Id, 0, messages.Count);
        }
    }

    private async Task<Dictionary<int, int>> BuildThreadCounts(List<Message> msgs)
    {
        var counts = new Dictionary<int, int>();
        foreach (var msg in msgs.Where(m => m.ReplyToId is null))
        {
            var thread = await ChatService.GetThreadAsync(msg.Id);
            if (thread.Count > 0)
                counts[msg.Id] = thread.Count;
        }
        return counts;
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

/* Channel Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

.sidebar-header {
    padding: 16px;
    border-bottom: 1px solid #202225;
}

.sidebar-header h5 {
    margin: 0;
    color: #fff;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-radius: 4px;
    margin: 2px 8px;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #36393f;
}

.channel-item.active {
    background: #393c43;
    color: #fff;
}

.channel-item-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

.unread-badge {
    background: #ed4245;
    color: #fff;
    border-radius: 10px;
    padding: 1px 6px;
    font-size: 0.75rem;
    font-weight: 700;
}

.channel-description {
    font-size: 0.8rem;
    color: #8e9297;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    margin-top: 2px;
}

/* Main Message Area */
.chat-main {
    flex: 1;
    display: flex;
    min-width: 0;
}

.chat-main.with-thread {
    flex: 0 0 55%;
}

.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #36393f;
    color: #dcddde;
}

.message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

.message-area-header h5 {
    margin: 0;
    color: #fff;
}

.message-area-header .channel-desc {
    margin: 4px 0 0;
    font-size: 0.85rem;
    color: #8e9297;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px;
}

.loading-indicator {
    text-align: center;
    padding: 8px;
    color: #8e9297;
    font-size: 0.85rem;
}

.no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #36393f;
    color: #8e9297;
}

/* Message Bubble */
.message-bubble {
    padding: 8px 12px;
    border-radius: 4px;
    margin-bottom: 4px;
    position: relative;
    transition: background 0.1s;
}

.message-bubble:hover {
    background: #32353b;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 4px;
}

.message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.95rem;
}

.message-time {
    font-size: 0.75rem;
    color: #72767d;
}

.message-content {
    line-height: 1.4;
    word-wrap: break-word;
}

.message-reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 6px;
}

.reaction-badge {
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px 6px;
    font-size: 0.85rem;
    cursor: pointer;
    transition: background 0.15s;
}

.reaction-badge:hover {
    background: #4f545c;
}

.thread-link {
    font-size: 0.8rem;
    color: #00aff4;
    cursor: pointer;
    margin-top: 4px;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -4px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px;
}

.btn-action {
    background: none;
    border: none;
